// --- REPORTS & HISTORY ---

router.get('/reports/monthly', async (req: Request, res: Response) => {
  try {
    const userId = (req.query.userId as string) || '';
    const month = (req.query.month as string) || new Date().toISOString().slice(0, 7);

    if (!userId) {
      return res.json({
        month,
        mealTotal: 0,
        expenseTotal: 0,
        paymentTotal: 0,
        remainingBalance: 0,
        categories: []
      });
    }

    const { data: meals } = await supabase.from('Meal').select('*').eq('userId', userId);
    const { data: expenses } = await supabase.from('Expense').select('*').eq('userId', userId);
    const { data: payments } = await supabase.from('Payment').select('*').eq('userId', userId).eq('status', 'APPROVED');

    const mList = (meals || []).filter(m => String(m.date).startsWith(month));
    const eList = (expenses || []).filter(e => String(e.date).startsWith(month));

    const mealTotal = mList.reduce((acc, m) => acc + (m.totalCost || 0), 0);
    const expenseTotal = eList.reduce((acc, e) => acc + (e.amount || 0), 0);
    const paymentTotal = (payments || []).reduce((acc, p) => acc + (p.amount || 0), 0);

    // Group expenses by category
    const catMap: Record<string, number> = {};
    if (mealTotal > 0) catMap['Tiffin & Mess Meals'] = mealTotal;

    for (const exp of eList) {
      catMap[exp.category] = (catMap[exp.category] || 0) + exp.amount;
    }

    const totalSpent = mealTotal + expenseTotal;
    const categories = Object.entries(catMap).map(([name, amount]) => ({
      name,
      amount,
      pct: totalSpent > 0 ? Math.round((amount / totalSpent) * 100) + '%' : '0%'
    }));

    res.json({
      month,
      mealTotal,
      expenseTotal,
      paymentTotal,
      remainingBalance: Math.max(0, totalSpent - paymentTotal),
      categories
    });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

